window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 10000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await sleep(150) } return false };
window.nav = async (name) => { const b = [...document.querySelectorAll('nav button')].find((x) => x.textContent.trim() === name); if (!b) return 'NO NAV ' + name; b.click(); await sleep(1800); return 'nav ' + name };
window.setInput = (input, value) => { const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, value); input.dispatchEvent(new Event('input', { bubbles: true })); input.dispatchEvent(new Event('change', { bubbles: true })) };
window.chooseSelect = async (title, value) => { const el = [...document.querySelectorAll('select')].find((x) => x.title === title); if (!el) return 'NO SELECT ' + title; Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, String(value)); el.dispatchEvent(new Event('change', { bubbles: true })); await sleep(1500); return title + ' = ' + (el.selectedOptions[0]?.textContent ?? el.value) };
window.clickText = async (text) => { const b = [...document.querySelectorAll('button,[role=tab]')].find((x) => x.textContent.trim() === text); if (!b) return 'NO BUTTON ' + text; b.click(); await sleep(1500); return 'clicked ' + text };
window.cells = (r) => [...r.querySelectorAll('[role=cell],td')].map((c) => c.textContent.trim());
window.boardRow = (name) => { const r = [...document.querySelectorAll('tr,[role=row]')].find((x) => x.textContent.includes(name)); return r ? cells(r) : 'NO ROW ' + name };
window.splitRow = (group, label) => { const t = document.querySelector('[role=table][aria-label="' + group + '"]'); if (!t) return 'NO TABLE ' + group; const r = [...t.querySelectorAll('[role=row]')].find((x) => cells(x)[0] === label); return r ? cells(r) : 'NO ROW ' + label };
window.groupNote = (group) => { const t = document.querySelector('[role=table][aria-label="' + group + '"]'); return t?.closest('section')?.querySelector('div.text-fg-3')?.textContent ?? 'NO NOTE' };
window.openPlayer = async (name) => { const input = document.querySelector('input[aria-label="Search players"]'); if (!input) return 'NO SEARCH'; setInput(input, name); await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED ' + name; b.click(); await sleep(2000); return 'opened ' + name };
window.check = (label, got, want) => (want.every((w) => JSON.stringify(got).includes(w)) ? 'OK ' : 'MISMATCH ') + label + ' want ' + JSON.stringify(want) + ' got ' + JSON.stringify(got);
window.footer = () => [...document.querySelectorAll('footer div')].map((d) => d.textContent).filter((t) => t.length < 400);
