window.section = (title) => [...document.querySelectorAll('section')].find((s) => s.innerText.trim().startsWith(title))?.innerText.replace(/\n+/g, ' | ') ?? 'NO SECTION ' + title;
window.titles = (re) => [...document.querySelectorAll('[title]')].map((x) => x.title).filter((t) => re.test(t));
window.heads = () => [...document.querySelectorAll('thead th,[role=columnheader]')].map((t) => t.textContent.trim()).filter(Boolean);
